def check(part):
    """Check whether a part meets the zoned equivalent-diameter porosity criterion."""
    zones = part.get("zones", [])
    pores = part.get("pores", [])

    limits_by_rank = {
        2: 0.20,  # sealing
        1: 0.40,  # machined
        0: 1.00,  # everything else
    }

    def zone_rank(name):
        normalized = name.strip().lower()
        if normalized == "sealing":
            return 2
        if normalized == "machined":
            return 1
        return 0

    ranked_zones = [
        (zone_rank(zone["name"]), zone["box"])
        for zone in zones
    ]

    for pore in pores:
        x, y, z = pore["centroid"]
        assigned_rank = 0
        for rank, box in ranked_zones:
            if rank <= assigned_rank:
                continue
            xmin, xmax, ymin, ymax, zmin, zmax = box
            if xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax:
                assigned_rank = rank
                if assigned_rank == 2:
                    break

        if pore["d_eq_mm"] > limits_by_rank[assigned_rank]:
            return False

    return True
```

ASSUMPTIONS:
- Zone names are matched case-insensitively (ignoring leading/trailing whitespace) against the exact strings "sealing" and "machined"; any other zone name is categorized as "everything else".
- Pores whose centroids are not contained in any zone listed in `part["zones"]` are categorized as "everything else" (limit 1.00 mm).
- "Exceeds the limit" is treated as strictly greater than (`d_eq_mm > limit`), so a pore with `d_eq_mm` equal to its assigned zone's limit is accepted.
- Each zone box is assumed to have ordered bounds (`xmin <= xmax`, `ymin <= ymax`, `zmin <= zmax`).
- A part with no pores is accepted.

```python
def check(part):
    sealing_boxes = []
    machined_boxes = []

    for zone in part.get("zones", []):
        name = zone["name"].strip().lower()
        if name == "sealing":
            sealing_boxes.append(zone["box"])
        elif name == "machined":
            machined_boxes.append(zone["box"])

    def contains(box, point):
        xmin, xmax, ymin, ymax, zmin, zmax = box
        x, y, z = point
        return xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax

    for pore in part.get("pores", []):
        centroid = pore["centroid"]
        if any(contains(box, centroid) for box in sealing_boxes):
            limit = 0.20
        elif any(contains(box, centroid) for box in machined_boxes):
            limit = 0.40
        else:
            limit = 1.00

        if pore["d_eq_mm"] > limit:
            return False

    return True
```

ASSUMPTIONS:
- Zone names are matched case-insensitively with leading/trailing whitespace ignored (`"sealing"` and `"machined"` exact names, not substrings).
- Pores whose centroids do not fall inside any zone listed in `part["zones"]` are treated as belonging to "everything else" (1.00 mm limit).
- "Exceeds" is interpreted as strictly greater than (`>`), so a pore with `d_eq_mm` equal to its zone's limit is accepted.
- A part with no pores is accepted.

