import math


def check(part):
    cube_edge = 5.0
    min_d_eq = 0.10
    max_pores = 4
    cell_size = 4.0

    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]
    if len(points) <= max_pores:
        return True

    # Partition space into 4.0 mm cells. Any cell containing > 4 qualifying
    # centroids automatically fits inside a 5.0 mm cube, so reject immediately.
    grid = {}
    for pt in points:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        bucket = grid.get(key)
        if bucket is None:
            grid[key] = [pt]
        else:
            bucket.append(pt)
            if len(bucket) > max_pores:
                return False

    # Any 5.0 mm cube containing >= 5 centroids can be shifted so its minimum-x
    # face passes through one of those centroids. All other centroids in that
    # cube must lie within dx in [0, 2] and dy, dz in [-2, 2] of its 4.0 mm cell.
    for (cx, cy, cz), cell_points in grid.items():
        neighbors = []
        for dx in (0, 1, 2):
            nx = cx + dx
            for dy in (-2, -1, 0, 1, 2):
                ny = cy + dy
                for dz in (-2, -1, 0, 1, 2):
                    bucket = grid.get((nx, ny, cz + dz))
                    if bucket is not None:
                        neighbors.extend(bucket)

        if len(neighbors) <= max_pores:
            continue

        for x0, y_anchor, z_anchor in cell_points:
            x_hi = x0 + cube_edge
            y_min = y_anchor - 5.1
            y_max = y_anchor + 5.1
            z_min = z_anchor - 5.1
            z_max = z_anchor + 5.1

            cands = [
                (p[1], p[2])
                for p in neighbors
                if x0 <= p[0] <= x_hi
                and y_min <= p[1] <= y_max
                and z_min <= p[2] <= z_max
            ]
            n_cands = len(cands)
            if n_cands <= max_pores:
                continue

            cands.sort()
            r = 0
            for i in range(n_cands - max_pores):
                y_hi = cands[i][0] + cube_edge
                while r < n_cands and cands[r][0] <= y_hi:
                    r += 1
                if r - i > max_pores:
                    zs = sorted(cands[k][1] for k in range(i, r))
                    for k in range(len(zs) - max_pores):
                        if zs[k + max_pores] <= zs[k] + cube_edge:
                            return False
                if r == n_cands:
                    break

    return True
```

ASSUMPTIONS:
The criterion applies globally to all pores in `part["pores"]` without restriction to any specific inspection zone or to cubes wholly enclosed within the part geometry.
Threshold and cube-boundary checks use standard IEEE 754 floating-point inequalities (`d_eq_mm >= 0.10` and closed intervals `[c0, c0 + 5.0]`) without an additional numerical tolerance.

