import math


def check(part):
    """Return True if at most 3 pores with d_eq_mm >= 0.15 exist in any
    axis-aligned 5 mm x 5 mm x 5 mm reference volume, else False.
    """
    min_d_eq = 0.15
    box_size = 5.0
    max_pores = 3

    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part.get("pores", [])
        if p["d_eq_mm"] >= min_d_eq
    ]

    if len(points) <= max_pores:
        return True

    # Partition qualifying pore centroids into a spatial grid of cube size box_size.
    grid = {}
    for pt in points:
        key = (
            math.floor(pt[0] / box_size),
            math.floor(pt[1] / box_size),
            math.floor(pt[2] / box_size),
        )
        cell = grid.get(key)
        if cell is None:
            grid[key] = [pt]
        else:
            cell.append(pt)
            if len(cell) > max_pores:
                xs = [c[0] for c in cell]
                ys = [c[1] for c in cell]
                zs = [c[2] for c in cell]
                if (
                    max(xs) - min(xs) <= box_size
                    and max(ys) - min(ys) <= box_size
                    and max(zs) - min(zs) <= box_size
                ):
                    return False

    # Any set of > max_pores points fitting in a closed axis-aligned
    # box_size^3 cube has a minimum-x point `a` and minimum-y point `b`.
    # For each candidate `a`, collect all points within [0, box_size] in x
    # and [-box_size, box_size] in y and z, then sweep y-windows of width
    # box_size and check for > max_pores points within a z-window of box_size.
    eps = 1e-9
    for ax, ay, az in points:
        cx_min = math.floor(ax / box_size - eps)
        cx_max = math.floor((ax + box_size) / box_size + eps)
        cy_min = math.floor((ay - box_size) / box_size - eps)
        cy_max = math.floor((ay + box_size) / box_size + eps)
        cz_min = math.floor((az - box_size) / box_size - eps)
        cz_max = math.floor((az + box_size) / box_size + eps)

        candidates = []
        for cx in range(cx_min, cx_max + 1):
            for cy in range(cy_min, cy_max + 1):
                for cz in range(cz_min, cz_max + 1):
                    cell = grid.get((cx, cy, cz))
                    if cell is None:
                        continue
                    for px, py, pz in cell:
                        if (
                            0.0 <= px - ax <= box_size
                            and abs(py - ay) <= box_size
                            and abs(pz - az) <= box_size
                        ):
                            candidates.append((py, pz))

        if len(candidates) <= max_pores:
            continue

        candidates.sort(key=lambda item: item[0])
        n_cand = len(candidates)
        right = 0
        for left in range(n_cand):
            if left > 0 and candidates[left][0] == candidates[left - 1][0]:
                continue
            by = candidates[left][0]
            while right < n_cand and candidates[right][0] - by <= box_size:
                right += 1
            if right - left > max_pores:
                zs = sorted(candidates[i][1] for i in range(left, right))
                for i in range(len(zs) - max_pores):
                    if zs[i + max_pores] - zs[i] <= box_size:
                        return False

    return True
```

ASSUMPTIONS:
- "0.15 mm or more" is interpreted as inclusive (`d_eq_mm >= 0.15`); pores with `d_eq_mm < 0.15` are ignored.
- "per 5 mm x 5 mm x 5 mm reference volume" is interpreted as a sliding (arbitrarily translated), axis-aligned closed cube of edge length 5.0 mm anywhere in 3D space, rather than a fixed grid or arbitrarily rotated cube.
- A pore is counted as inside a reference volume if its `centroid` falls within or on the boundary of the closed 5 mm x 5 mm x 5 mm cube (`span <= 5.0` along each axis); pore `bbox` intersection/containment is not used.
- The check applies globally to all pores in `part["pores"]` regardless of `zones`, `dist_surface_mm`, `wall_mm`, or `sphericity`.
- Reference volumes are not restricted to lie wholly inside the part's outer surface geometry (any 5 mm x 5 mm x 5 mm region in space is checked).

```python
import math


def check(part):
    """
    Porosity acceptance check based on equivalent diameter (d_eq) per zone.

    Each pore is assigned to the highest-ranked zone containing its centroid
    (boundaries inclusive). Ranking: sealing > machined > everything else.
    Limits: sealing 0.20 mm, machined 0.40 mm, everything else 1.00 mm.
    Returns False (reject) if any pore's d_eq strictly exceeds its zone limit.
    """
    LIMITS = {
        "sealing": 0.20,
        "machined": 0.40,
        "other": 1.00,
    }
    RANK = {"sealing": 2, "machined": 1, "other": 0}

    def zone_class(name):
        # Only zones named exactly "sealing" or "machined" (case/whitespace-insensitive)
        # get the tighter limits. Any other name counts as "everything else".
        n = str(name).strip().lower()
        if n == "sealing":
            return "sealing"
        if n == "machined":
            return "machined"
        return "other"

    def contains(box, pt):
        # Inclusive containment; tolerate boxes whose min/max are swapped.
        for axis in range(3):
            lo, hi = box[2 * axis], box[2 * axis + 1]
            if lo > hi:
                lo, hi = hi, lo
            if not (lo <= pt[axis] <= hi):
                return False
        return True

    def as_finite(value):
        try:
            v = float(value)
        except (TypeError, ValueError):
            return None
        return v if math.isfinite(v) else None

    # Pre-classify zones, skipping malformed boxes.
    zones = []
    for z in part.get("zones", []) or []:
        box = z.get("box")
        if not isinstance(box, (list, tuple)) or len(box) != 6:
            continue
        box_vals = [as_finite(b) for b in box]
        if any(b is None for b in box_vals):
            continue
        zones.append((zone_class(z.get("name", "")), box_vals))

    for pore in part.get("pores", []) or []:
        # Equivalent diameter; fall back to computing it from volume if absent.
        d_eq = as_finite(pore.get("d_eq_mm"))
        if d_eq is None:
            vol = as_finite(pore.get("volume_mm3"))
            if vol is None or vol < 0:
                return False  # cannot evaluate the pore -> fail closed
            d_eq = (6.0 * vol / math.pi) ** (1.0 / 3.0)

        centroid = pore.get("centroid")
        if not isinstance(centroid, (list, tuple)) or len(centroid) != 3:
            return False  # cannot locate the pore -> fail closed
        pt = [as_finite(c) for c in centroid]
        if any(c is None for c in pt):
            return False

        # Assign to the highest-ranked zone containing the centroid.
        assigned = "other"
        for cls, box in zones:
            if RANK[cls] > RANK[assigned] and contains(box, pt):
                assigned = cls
                if assigned == "sealing":
                    break  # highest rank possible

        if d_eq > LIMITS[assigned]:
            return False

    return True
```

**Assumptions to confirm against your spec:**

- **Zone names:** Only names exactly equal to `"sealing"` or `"machined"` (ignoring case and surrounding whitespace) get the tighter limits. Names like `"sealing_face_A"` are treated as "everything else." If your zones use prefixes or suffixes, switch the match to `startswith` or `in`.
- **"Exceeds":** This means strictly greater than. A pore at exactly 0.20 mm in a sealing zone passes. No floating-point tolerance is applied.
- **Pores outside every zone:** These get the "everything else" limit of 1.00 mm.
- **Fail-closed on bad data:**
  - If a pore has no usable centroid, the part is rejected.
  - If a pore has no `d_eq_mm`, the value is computed from `volume_mm3`. If that is also missing, the part is rejected.
  - Malformed zone boxes are ignored, which means pores inside them fall back to lower-ranked zones.

```python
import math


def check(part):
    """
    Acceptance criterion:
    "No pore with an equivalent diameter above 0.20 mm is permitted in the sealing zone."

    Returns True if the part is accepted, False if it is rejected.
    """
    D_EQ_LIMIT_MM = 0.20

    def _norm(name):
        return "".join(ch for ch in str(name).lower() if ch.isalnum())

    sealing_names = {"sealing", "sealingzone", "seal", "sealzone"}

    sealing_boxes = [
        z["box"] for z in part.get("zones", [])
        if _norm(z.get("name", "")) in sealing_names
    ]

    # The criterion cannot be evaluated without a sealing zone, so reject.
    if not sealing_boxes:
        return False

    def _intervals_overlap(a_min, a_max, b_min, b_max):
        return a_min <= b_max and b_min <= a_max

    def _boxes_overlap(a, b):
        return (_intervals_overlap(a[0], a[1], b[0], b[1]) and
                _intervals_overlap(a[2], a[3], b[2], b[3]) and
                _intervals_overlap(a[4], a[5], b[4], b[5]))

    def _point_in_box(p, b):
        return (b[0] <= p[0] <= b[1] and
                b[2] <= p[1] <= b[3] and
                b[4] <= p[2] <= b[5])

    def _d_eq(pore):
        d = pore.get("d_eq_mm")
        if d is not None:
            return float(d)
        v = pore.get("volume_mm3")
        if v is not None:
            return (6.0 * float(v) / math.pi) ** (1.0 / 3.0)
        return None

    for pore in part.get("pores", []):
        d = _d_eq(pore)
        if d is None:
            # Size unknown: cannot prove conformance.
            in_zone = True
        else:
            if not d > D_EQ_LIMIT_MM:
                continue

        bbox = pore.get("bbox")
        centroid = pore.get("centroid")
        in_zone = False
        for box in sealing_boxes:
            if bbox is not None and _boxes_overlap(bbox, box):
                in_zone = True
                break
            if centroid is not None and _point_in_box(centroid, box):
                in_zone = True
                break
            if bbox is None and centroid is None:
                # Location unknown: cannot prove the pore is outside the zone.
                in_zone = True
                break

        if in_zone:
            return False

    return True
```

ASSUMPTIONS:
- The sealing zone is identified by zone name. Names are normalized to lowercase alphanumerics, and a zone matches if the result is "sealing", "sealingzone", "seal" or "sealzone". For example, "Sealing Zone", "sealing_zone" and "SEAL" all match. A name like "non-sealing" does not match.
- If several zones match, the sealing zone is the union of all their boxes.
- If no sealing zone is defined in the data, the part is rejected because the criterion cannot be verified.
- "Above 0.20 mm" means strictly greater than 0.20 mm. A pore with d_eq exactly 0.20 mm is permitted. No measurement tolerance or rounding is applied.
- A pore counts as "in the sealing zone" if its bounding box overlaps the zone box at all, including partial overlap and touching at the boundary. The centroid is only used if no bbox is available. This is conservative: a pore whose bbox corner overlaps the zone may be flagged even if the pore material itself does not enter the zone.
- Zone box boundaries are treated as inclusive (closed intervals).
- If d_eq_mm is missing, it is computed from volume_mm3 as (6V/π)^(1/3).
- If both d_eq_mm and volume_mm3 are missing, the pore is treated as exceeding the limit and is checked for zone location.
- If a pore has neither a bbox nor a centroid, it is treated as inside the sealing zone.
- Only d_eq_mm is used for the size check. feret_max_mm, sphericity, dist_surface_mm and wall_mm are ignored, since the criterion only mentions equivalent diameter.
- Open-to-surface pores (dist_surface_mm = 0) are treated the same as internal pores.
- part_volume_mm3 and nominal_wall_mm are not used.

