def check(part):
    import math

    edge = 5.0

    # Retain only pores subject to the criterion.
    points = [
        tuple(pore["centroid"])
        for pore in part["pores"]
        if pore["d_eq_mm"] >= 0.10
    ]

    if len(points) <= 4:
        return True

    # Divide space into half-open 5 mm grid cells. Any five points in one
    # cell necessarily fit within a closed 5 mm cube.
    cells = {}
    for point in points:
        cell = tuple(math.floor(coordinate / edge) for coordinate in point)
        cells.setdefault(cell, []).append(point)
        if len(cells[cell]) >= 5:
            return False

    def contains_five_in_cube(candidate_points):
        """Return True if five candidates fit in some closed 5 mm cube."""
        by_x = sorted(candidate_points, key=lambda p: p[0])

        for i, point in enumerate(by_x):
            x0 = point[0]
            if i > 0 and by_x[i - 1][0] == x0:
                continue

            x_window = [
                p for p in by_x
                if x0 <= p[0] <= x0 + edge
            ]
            if len(x_window) < 5:
                continue

            by_y = sorted(x_window, key=lambda p: p[1])
            for j, y_point in enumerate(by_y):
                y0 = y_point[1]
                if j > 0 and by_y[j - 1][1] == y0:
                    continue

                z_values = sorted(
                    p[2] for p in by_y
                    if y0 <= p[1] <= y0 + edge
                )

                for k in range(len(z_values) - 4):
                    if z_values[k + 4] - z_values[k] <= edge:
                        return True

        return False

    # Every 5 mm cube intersects at most two adjacent grid cells along each
    # axis, so it is contained in one of these 2x2x2 cell blocks.
    blocks = set()
    for cx, cy, cz in cells:
        for dx in (-1, 0):
            for dy in (-1, 0):
                for dz in (-1, 0):
                    blocks.add((cx + dx, cy + dy, cz + dz))

    for bx, by, bz in blocks:
        candidates = []
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    candidates.extend(
                        cells.get((bx + dx, by + dy, bz + dz), ())
                    )

        if len(candidates) >= 5 and contains_five_in_cube(candidates):
            return False

    return True
```

