    pores = [p for p in part["pores"] if p["d_eq_mm"] >= 0.05]
    count = len(pores)

    parent = list(range(count))
    rank = [0] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(a, b):
        root_a = find(a)
        root_b = find(b)

        if root_a == root_b:
