        if root not in clusters:
            clusters[root] = {"count": 0, "diameter_sum": 0.0}
        clusters[root]["count"] += 1
        clusters[root]["diameter_sum"] += pore["d_eq_mm"]

    return all(
        cluster["count"] <= 5 and cluster["diameter_sum"] <= 1.0
        for cluster in clusters.values()
    )
