def check(part):
    zones = part.get("zones", [])
    pores = part.get("pores", [])

    limits_by_rank = {
        2: 0.20,  # sealing
        1: 0.40,  # machined
        0: 1.00,  # everything else
    }

    def zone_rank(name):
        normalized = name.strip().lower()
        if normalized == "sealing":
            return 2
        if normalized == "machined":
            return 1
        return 0

    for pore in pores:
        x, y, z = pore["centroid"]
        assigned_rank = 0

        for zone in zones:
            xmin, xmax, ymin, ymax, zmin, zmax = zone["box"]
            if xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax:
                rank = zone_rank(zone["name"])
                if rank > assigned_rank:
                    assigned_rank = rank
                    if assigned_rank == 2:
                        break

        if pore["d_eq_mm"] > limits_by_rank[assigned_rank]:
            return False

    return True
```

ASSUMPTIONS:
- Zone names are matched case-insensitively (ignoring surrounding whitespace) against the exact strings "sealing" and "machined"; all other zone names are categorized as "everything else".
- Pores whose centroids are outside all defined zones are assigned to the "everything else" category (1.00 mm limit).
- "Exceeds the limit" is treated as strictly greater than (`>`), so a pore with `d_eq_mm` equal to its zone limit is accepted.
- Parts with no pores are accepted (`True`).

```python
def check(part):
    """Return True if the part meets the zoned equivalent-diameter porosity criterion."""
    limits = {
        "sealing": 0.20,
        "machined": 0.40,
        "other": 1.00,
    }
    ranks = {
        "sealing": 2,
        "machined": 1,
        "other": 0,
    }

    zones = []
    for zone in part.get("zones", []):
        name = zone["name"].strip().lower()
        category = name if name in ("sealing", "machined") else "other"
        zones.append((ranks[category], category, zone["box"]))

    for pore in part.get("pores", []):
        x, y, z = pore["centroid"]
        assigned_rank = ranks["other"]
        assigned_category = "other"

        for rank, category, box in zones:
