    points = [
        (p["centroid"][0], p["centroid"][1], p["centroid"][2])
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]

    if len(points) < needed:
        return True

    get_x = itemgetter(0)
    get_y = itemgetter(1)

    def has_dense_cube(pts):
        n = len(pts)
        if n < needed:
            return False

        pts_x = sorted(pts, key=get_x)
        j = 0
        prev_j = 0
        for i in range(n - needed + 1):
            x_limit = pts_x[i][0] + edge
            while j < n and pts_x[j][0] <= x_limit:
                j += 1
            if j > prev_j:
                prev_j = j
                if j - i >= needed:
                    wx = sorted(pts_x[i:j], key=get_y)
                    m = len(wx)
                    yj = 0
                    prev_yj = 0
                    for yi in range(m - needed + 1):
                        y_limit = wx[yi][1] + edge
                        while yj < m and wx[yj][1] <= y_limit:
                            yj += 1
                        if yj > prev_yj:
                            prev_yj = yj
                            if yj - yi >= needed:
                                zs = sorted(p[2] for p in wx[yi:yj])
                                for k in range(len(zs) - needed + 1):
                                    if zs[k + max_pores] <= zs[k] + edge:
                                        return True
                        if yj == m:
                            break
            if j == n:
                break
        return False

    # Bucket qualifying centroids into 6.0 mm grid cells.
    cells = defaultdict(list)
    for pt in points:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        cells[key].append(pt)

    # A 6.0 mm cell is covered by 2x2x2 = 8 cubes of 5.0 mm (at most 32 pores if accepted).
    max_per_cell = 8 * max_pores
    for cell_pts in cells.values():
        c = len(cell_pts)
        if c > max_per_cell:
            return False
        if c >= needed and has_dense_cube(cell_pts):
            return False

    # Every 5.0 mm cube fits inside a 2x2x2 block of 6.0 mm cells.
    block_counts = defaultdict(int)
    for (cx, cy, cz), cell_pts in cells.items():
        c = len(cell_pts)
        for dx in (0, 1):
            ox = cx - dx
            for dy in (0, 1):
                oy = cy - dy
                for dz in (0, 1):
                    block_counts[(ox, oy, cz - dz)] += c

    # A 12.0 mm block is covered by 3x3x3 = 27 cubes of 5.0 mm (at most 108 pores if accepted).
    max_per_block = 27 * max_pores
    for (ox, oy, oz), total in block_counts.items():
        if total < needed:
            continue
        if total > max_per_block:
            return False

        block_pts = []
        num_cells = 0
        has_x0 = False
        has_y0 = False
        has_z0 = False
        for dx in (0, 1):
            nx = ox + dx
            for dy in (0, 1):
                ny = oy + dy
                for dz in (0, 1):
                    cell_pts = cells.get((nx, ny, oz + dz))
                    if cell_pts is not None:
                        num_cells += 1
                        if dx == 0:
                            has_x0 = True
                        if dy == 0:
                            has_y0 = True
                        if dz == 0:
                            has_z0 = True
                        block_pts.extend(cell_pts)

        if num_cells >= 2 and has_x0 and has_y0 and has_z0:
            if has_dense_cube(block_pts):
                return False

    return True
