from bisect import bisect_left
from collections import defaultdict
import math


def check(part: dict) -> bool:
    """Return True if the part is accepted, False if rejected.

    Rejects the part if any axis-aligned 5.0 mm cube (closed, i.e. faces count
    as inside) contains the centroids of more than 4 pores with d_eq_mm >= 0.10.
    """
    cube_edge = 5.0
    l_tol = cube_edge + 1e-12  # absorb IEEE-754 subtraction rounding on exact faces
    min_d_eq = 0.10
    max_pores = 4
    cell_size = 5.001  # strictly larger than l_tol so any 5.0 mm cube fits in a 2x2x2 block

    pts = [
        (float(p["centroid"][0]), float(p["centroid"][1]), float(p["centroid"][2]))
        for p in part["pores"]
        if p["d_eq_mm"] >= min_d_eq
    ]

    if len(pts) <= max_pores:
        return True

    # Partition space into cells of edge cell_size.
    cells: dict[tuple[int, int, int], list[tuple[float, float, float]]] = defaultdict(list)
    for pt in pts:
        key = (
            math.floor(pt[0] / cell_size),
            math.floor(pt[1] / cell_size),
            math.floor(pt[2] / cell_size),
        )
        cell_pts = cells[key]
        cell_pts.append(pt)
        # A cell of side 5.001 splits into 8 octants of side ~2.5005 < 5.0.
        # By Pigeonhole Principle, > 32 points guarantees an octant with >= 5 points.
        if len(cell_pts) > 8 * max_pores:
            return False

    # Count points in every 2x2x2 block of cells touching at least one occupied cell.
    block_counts: dict[tuple[int, int, int], int] = defaultdict(int)
    for (cx, cy, cz), cell_pts in cells.items():
        cnt = len(cell_pts)
        for dx in (0, 1):
            ax = cx - dx
            for dy in (0, 1):
                ay = cy - dy
                for dz in (0, 1):
                    bkey = (ax, ay, cz - dz)
                    new_cnt = block_counts[bkey] + cnt
                    # A 2x2x2 block of side 10.002 splits into 27 sub-cubes of side ~3.334 < 5.0.
                    # By Pigeonhole Principle, > 108 points guarantees a sub-cube with >= 5 points.
                    if new_cnt > 27 * max_pores:
                        return False
                    block_counts[bkey] = new_cnt

    def has_violating_square_yz(xw: list[tuple[float, float, float]]) -> bool:
        """Check whether y-sorted points contain > max_pores points in an l_tol x l_tol (y, z) square."""
        m = len(xw)
        if xw[-1][1] - xw[0][1] <= l_tol:
            zs = sorted(p[2] for p in xw)
            for k in range(m - max_pores):
                if zs[k + max_pores] - zs[k] <= l_tol:
                    return True
            return False

        zs: list[float] = []
        yj = 0
        for yi in range(m):
            y_lo = xw[yi][1]
            while yj < m and xw[yj][1] - y_lo <= l_tol:
                z = xw[yj][2]
                pos = bisect_left(zs, z)
                zs.insert(pos, z)
                n_z = len(zs)
                if n_z > max_pores:
                    lo = pos - max_pores if pos > max_pores else 0
                    hi = pos if pos <= n_z - max_pores - 1 else n_z - max_pores - 1
                    for k in range(lo, hi + 1):
                        if zs[k + max_pores] - zs[k] <= l_tol:
                            return True
                yj += 1
            if yj == m:
                break
            zs.pop(bisect_left(zs, xw[yi][2]))
        return False

    def has_violating_cube(block_pts: list[tuple[float, float, float]]) -> bool:
        """Exact 3D sweep-line check on the points of a candidate 2x2x2 cell block."""
        px = sorted(block_pts, key=lambda p: p[0])
        if px[-1][0] - px[0][0] <= l_tol:
            py = sorted(px, key=lambda p: p[1])
            return has_violating_square_yz(py)

        py = sorted(block_pts, key=lambda p: p[1])
        n = len(px)
        j = 0
        prev_j = 0
        for i in range(n):
            x_lo = px[i][0]
            while j < n and px[j][0] - x_lo <= l_tol:
                j += 1
            if j > prev_j:
                prev_j = j
                if j - i > max_pores:
                    x_hi = px[j - 1][0]
                    xw = [p for p in py if x_lo <= p[0] <= x_hi]
                    if has_violating_square_yz(xw):
                        return True
                if j == n:
                    break
        return False

    for (ax, ay, az), total in block_counts.items():
        if total <= max_pores:
            continue
        block_pts = []
        for dx in (0, 1):
            for dy in (0, 1):
                for dz in (0, 1):
                    cpts = cells.get((ax + dx, ay + dy, az + dz))
                    if cpts:
                        block_pts.extend(cpts)
        if has_violating_cube(block_pts):
            return False

    return True
