import math
from collections import defaultdict


def check(part):
    pores = part.get("pores", [])
    considered = []
    max_d = 0.0

    for pore in pores:
        d = pore["d_eq_mm"]
        if d >= 0.05:
            if d > 1.0:
                return False
            considered.append((pore["centroid"], d))
            if d > max_d:
                max_d = d

    n = len(considered)
    if n == 0:
        return True

    parent = list(range(n))
    size = [1] * n

    def find(i):
        while parent[i] != i:
            parent[i] = parent[parent[i]]
            i = parent[i]
        return i

    def union(i, j):
        ri = find(i)
        rj = find(j)
        if ri == rj:
            return False
        if size[ri] < size[rj]:
            ri, rj = rj, ri
        parent[rj] = ri
        size[ri] += size[rj]
        return size[ri] > 5

    cell_size = 0.50 + max_d + 1e-6
    grid = defaultdict(list)
    for idx, (centroid, _) in enumerate(considered):
        cell = (
            math.floor(centroid[0] / cell_size),
            math.floor(centroid[1] / cell_size),
            math.floor(centroid[2] / cell_size),
        )
        grid[cell].append(idx)

    neighbor_offsets = [
        (dx, dy, dz)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        for dz in (-1, 0, 1)
        if (dx, dy, dz) > (0, 0, 0)
    ]

    for cell, indices in grid.items():
        m = len(indices)
        for a in range(m):
            i = indices[a]
            ci, di = considered[i]
            for b in range(a + 1, m):
                j = indices[b]
                if find(i) == find(j):
                    continue
                cj, dj = considered[j]
                gap = math.dist(ci, cj) - 0.5 * (di + dj)
                if gap < 0.50:
                    if union(i, j):
                        return False

        gx, gy, gz = cell
        for dx, dy, dz in neighbor_offsets:
            other = grid.get((gx + dx, gy + dy, gz + dz))
            if not other:
                continue
            for i in indices:
                ci, di = considered[i]
                for j in other:
                    if find(i) == find(j):
                        continue
                    cj, dj = considered[j]
                    gap = math.dist(ci, cj) - 0.5 * (di + dj)
                    if gap < 0.50:
                        if union(i, j):
