from collections import defaultdict


def check(part):
    pores = [p for p in part["pores"] if p["d_eq_mm"] >= 0.05]
    if not pores:
        return True

    # Treat single pores as clusters of size 1; reject immediately if any exceeds 1.0 mm.
    # For all remaining pores, d_eq_mm <= 1.0, so any two neighbours have centroid
    # distance < 0.50 + 0.5 * (1.0 + 1.0) = 1.50 mm.
    for p in pores:
        if p["d_eq_mm"] > 1.0:
            return False

    n = len(pores)
    parent = list(range(n))
    rank = [0] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra == rb:
            return
        if rank[ra] < rank[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        if rank[ra] == rank[rb]:
            rank[ra] += 1

    cell_size = 1.51
    grid = defaultdict(list)
    coords = [p["centroid"] for p in pores]
    diams = [p["d_eq_mm"] for p in pores]

    for i, c in enumerate(coords):
        cell = (
            math.floor(c[0] / cell_size),
            math.floor(c[1] / cell_size),
            math.floor(c[2] / cell_size),
        )
        grid[cell].append(i)

    positive_offsets = [
        (dx, dy, dz)
        for dx in (-1, 0, 1)
        for dy in (-1, 0, 1)
        for dz in (-1, 0, 1)
        if (dx, dy, dz) > (0, 0, 0)
    ]

    for cell, indices in grid.items():
        cx, cy, cz = cell
        m = len(indices)
        for a_idx in range(m):
            i = indices[a_idx]
            ci = coords[i]
            di = diams[i]
            for b_idx in range(a_idx + 1, m):
                j = indices[b_idx]
                if math.dist(ci, coords[j]) - 0.5 * (di + diams[j]) < 0.50:
                    union(i, j)

        for dx, dy, dz in positive_offsets:
            nb_indices = grid.get((cx + dx, cy + dy, cz + dz))
            if not nb_indices:
                continue
            for i in indices:
                ci = coords[i]
                di = diams[i]
                for j in nb_indices:
                    if math.dist(ci, coords[j]) - 0.5 * (di + diams[j]) < 0.50:
                        union(i, j)

    clusters = defaultdict(list)
    for i in range(n):
        clusters[find(i)].append(diams[i])

    for cluster_diams in clusters.values():
        if len(cluster_diams) > 5 or math.fsum(cluster_diams) > 1.0:
