```python
import math


def check(part):
    pores = [p for p in part["pores"] if p["d_eq_mm"] >= 0.05]
    if not pores:
        return True

    # A single pore with d_eq_mm > 1.0 forms a cluster exceeding the 1.0 mm limit.
    for p in pores:
        if p["d_eq_mm"] > 1.0:
            return False

    n = len(pores)
    if n == 1:
        return True

    # Choose the axis with the widest spread for sweep-and-prune neighbour search.
    spreads = [
        max(p["centroid"][axis] for p in pores) - min(p["centroid"][axis] for p in pores)
        for axis in range(3)
    ]
    axis = spreads.index(max(spreads))

    # Two pores are neighbours iff dist < 0.50 + 0.5 * (di + dj) = ri + rj,
    # where r = 0.25 + 0.5 * d_eq_mm.
    items = []
    for p in pores:
        c = p["centroid"]
        d = p["d_eq_mm"]
        r = 0.25 + 0.5 * d
        coord = c[axis]
        items.append((coord - r, coord + r, (c[0], c[1], c[2]), d, r))
    items.sort(key=lambda item: item[0])

    parent = list(range(n))
    size = [1] * n

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra = find(a)
        rb = find(b)
        if ra == rb:
            return size[ra]
        if size[ra] < size[rb]:
            ra, rb = rb, ra
        parent[rb] = ra
        size[ra] += size[rb]
        return size[ra]

    eps = 1e-9
    for i in range(n):
        _, right_i, ci, di, ri = items[i]
        xi, yi, zi = ci
        for j in range(i + 1, n):
            left_j, _, cj, dj, rj = items[j]
            if left_j > right_i + eps:
                break
            if find(i) == find(j):
                continue
            limit = ri + rj + eps
            if (
                abs(xi - cj[0]) > limit
                or abs(yi - cj[1]) > limit
                or abs(zi - cj[2]) > limit
            ):
                continue
            if math.dist(ci, cj) - 0.5 * (di + dj) < 0.50:
                if union(i, j) > 5:
                    return False

    clusters = {}
    for i in range(n):
        root = find(i)
        clusters.setdefault(root, []).append(items[i][3])

    for diameters in clusters.values():
        if len(diameters) > 5 or math.fsum(diameters) > 1.0:
            return False

    return True
