def check(part):
    """Return True if the part meets the zone porosity acceptance criterion, False otherwise."""
    max_porosity = 0.001  # 0.10%
    pores = part.get("pores", [])

    for zone in part.get("zones", []):
        xmin, xmax, ymin, ymax, zmin, zmax = zone["box"]
        zone_volume = (xmax - xmin) * (ymax - ymin) * (zmax - zmin)

        pore_volume_sum = 0.0
        for pore in pores:
            x, y, z = pore["centroid"]
            if xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax:
                pore_volume_sum += pore["volume_mm3"]

        if zone_volume <= 0.0:
            if pore_volume_sum > 0.0:
                return False
            continue

        if (pore_volume_sum / zone_volume) > max_porosity:
            return False

    return True
