def check(part: dict) -> bool:
    """Return True if no pore with equivalent diameter > 0.20 mm intersects the sealing zone."""
    max_d_eq_mm = 0.20

    sealing_boxes = [
        zone["box"]
        for zone in part.get("zones", [])
        if _is_sealing_zone(zone.get("name", ""))
    ]
    if not sealing_boxes:
        return True

    for pore in part.get("pores", []):
        if pore["d_eq_mm"] <= max_d_eq_mm:
