    if re.search(r"non[\s_-]*sealing", low):
        return False
    return "sealing" in low


def _boxes_overlap(box_a: list, box_b: list) -> bool:
    return (
        box_a[0] <= box_b[1] and box_a[1] >= box_b[0]
        and box_a[2] <= box_b[3] and box_a[3] >= box_b[2]
        and box_a[4] <= box_b[5] and box_a[5] >= box_b[4]
