        norm = re.sub(r"[\s_\-]+", " ", zone.get("name", "").strip().lower())
        if norm in ("sealing", "sealing zone"):
            sealing_boxes.append(zone["box"])

    # Fallback: match zones tagged with "sealing" (e.g., "sealing_1", "sealing_face"),
    # excluding negated or exterior zone names (e.g., "non_sealing", "outside_sealing")
    if not sealing_boxes:
        excluded_modifiers = {"non", "no", "not", "outside", "near"}
        for zone in zones:
            tokens = set(re.findall(r"[a-z0-9]+", zone.get("name", "").lower()))
            if "sealing" in tokens and not (tokens & excluded_modifiers):
