    norm_sealing_boxes = [
        (
            min(b[0], b[1]), max(b[0], b[1]),
            min(b[2], b[3]), max(b[2], b[3]),
            min(b[4], b[5]), max(b[4], b[5]),
        )
        for b in sealing_boxes
    ]

    for pore in part.get("pores", []):
        if pore["d_eq_mm"] <= max_d_eq_mm:
            continue

        bbox = pore.get("bbox")
        if bbox is not None:
            pxmin, pxmax = min(bbox[0], bbox[1]), max(bbox[0], bbox[1])
            pymin, pymax = min(bbox[2], bbox[3]), max(bbox[2], bbox[3])
            pzmin, pzmax = min(bbox[4], bbox[5]), max(bbox[4], bbox[5])
