import re


def _is_sealing_zone(name: str) -> bool:
    """Identify inspection zones corresponding to the sealing zone."""
    normalized = re.sub(r"([a-z])([A-Z])", r"\1_\2", name.strip())
    tokens = [t for t in re.split(r"[\s_\-\d]+", normalized.lower()) if t]
    return "sealing" in tokens and "non" not in tokens


def _boxes_intersect(box_a, box_b) -> bool:
    """Return True if two axis-aligned boxes [xmin, xmax, ymin, ymax, zmin, zmax] intersect."""
    axmin, axmax, aymin, aymax, azmin, azmax = box_a
    bxmin, bxmax, bymin, bymax, bzmin, bzmax = box_b
    return (
        axmin <= bxmax
        and axmax >= bxmin
        and aymin <= bymax
        and aymax >= bymin
        and azmin <= bzmax
        and azmax >= bzmin
    )


def _point_in_box(point, box) -> bool:
    """Return True if point [x, y, z] lies inside or on the boundary of box."""
    x, y, z = point
    xmin, xmax, ymin, ymax, zmin, zmax = box
    return xmin <= x <= xmax and ymin <= y <= ymax and zmin <= z <= zmax


def check(part: dict) -> bool:
    """Return True if no pore with an equivalent diameter above 0.20 mm is in the sealing zone."""
    max_d_eq_mm = 0.20

    sealing_boxes = [
        zone["box"]
        for zone in part.get("zones", [])
        if _is_sealing_zone(zone["name"])
    ]
    if not sealing_boxes:
        return True

    for pore in part.get("pores", []):
        if pore["d_eq_mm"] <= max_d_eq_mm:
            continue

        bbox = pore.get("bbox")
        centroid = pore.get("centroid")
        for zbox in sealing_boxes:
            if (bbox is not None and _boxes_intersect(bbox, zbox)) or (
                centroid is not None and _point_in_box(centroid, zbox)
            ):
                return False

    return True
